import React, { useId } from "react";
import type { StickerProps } from "../types";
import { usePeel } from "../utils/usePeel";

export const SocialNetworkBadgeSticker: React.FC<StickerProps> = ({
  size = 120,
  width,
  height,
  peel = false,
  className = "",
  style,
  ...props
}) => {
  const rawId = useId();
  const id = rawId.replace(/[:]/g, "_");

  const finalWidth = width ?? size;
  const finalHeight =
    height ?? (typeof size === "number" ? Math.round((size * 712) / 895) : size);
  const { style: peelStyle, onMouseEnter, onMouseLeave } = usePeel(peel, style);

  return (
    <svg
      width={finalWidth}
      height={finalHeight}
      viewBox="0 0 895 712"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
      className={className}
      style={peelStyle}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      aria-label="The Social Network Sticker"
      role="img"
      {...props}
    >
      <rect width="895" height="712" fill={`url(#p_social2_${id})`} />
      <defs>
        <pattern
          id={`p_social2_${id}`}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref={`#img_social2_${id}`}
            href={`#img_social2_${id}`}
            transform="matrix(0.0023264 0 0 0.00292398 -0.353668 0)"
          />
        </pattern>
        <image
          id={`img_social2_${id}`}
          width="735"
          height="342"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
          href="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
};
